import string
from nltk import pos_tag, word_tokenize
from nltk.stem import WordNetLemmatizer


class Lemmatization:
    def __init__(self):
        self.lemmatizer = WordNetLemmatizer()

    def lemmatize_sentence(self, sentence):
        return [
            self.lemmatize_word(word, tag)
            for word, tag in self.get_tagged_words(sentence)
        ]

    def get_tagged_words(self, sentence):
        cleaned_sentence = self.remove_punctuation(sentence)
        words = word_tokenize(cleaned_sentence)
        return pos_tag(words)

    def lemmatize_word(self, word, tag):
        if tag.startswith('V'):
            pos = 'v'
        elif tag.startswith('J'):
            pos = 'a'
        elif tag.startswith('R'):
            pos = 'r'
        else:
            pos = None
        if pos is None:
            return self.lemmatizer.lemmatize(word)
        return self.lemmatizer.lemmatize(word, pos=pos)

    def get_pos_tag(self, sentence):
        return [tag for _, tag in self.get_tagged_words(sentence)]

    def remove_punctuation(self, sentence):
        return sentence.translate(str.maketrans('', '', string.punctuation))
